// Des: Tests for M14: SSE, long-poll, WebSocket frames with caps
// Flo: mock feeds > sseRead / wsRead > assert exact frame count, deadline, frame cap, JSONL record
// I/O: mock server + local Chrome for WebSocket (skipped when absent) > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const rigz = @import("te-brow-rig.zig"); const strm = @import("nt-strm-read.zig"); const pipe = @import("ru-page-fetc.zig"); const cdp2 = @import("nt-brow-cdpz.zig");
const allo = std.testing.allocator;
fn url(rig3: *rigz.Rigg, buf4: []u8, path: []const u8) []const u8 { return rig3.srv2.urlzOfzz(buf4, path); }
test "SSE: exactly the 5 events, in order" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf4: [64]u8 = undefined; const got2 = try strm.ssezRead(allo, aren.allocator(), std.testing.io, url(&rig3, &buf4, "/sse"), .{ .priv = true, .time_mill = 5000 }); try std.testing.expectEqual(@as(usize, 5), got2.len); try std.testing.expectEqualStrings("msg1", got2[0]); try std.testing.expectEqualStrings("msg5", got2[4]); }
test "frame cap stops an endless feed fast" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf4: [64]u8 = undefined; const t0zz = cdp2.nowzMill(std.testing.io); const got2 = try strm.ssezRead(allo, aren.allocator(), std.testing.io, url(&rig3, &buf4, "/sseinf"), .{ .priv = true, .time_mill = 20000, .fra2 = 7 }); try std.testing.expectEqual(@as(usize, 7), got2.len); try std.testing.expect(cdp2.nowzMill(std.testing.io) - t0zz < 5000); }
test "deadline stops an endless feed" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf4: [64]u8 = undefined; const t0zz = cdp2.nowzMill(std.testing.io); const got2 = try strm.ssezRead(allo, aren.allocator(), std.testing.io, url(&rig3, &buf4, "/sseinf"), .{ .priv = true, .time_mill = 400 }); try std.testing.expect(got2.len >= 1 and got2.len < 100); try std.testing.expect(cdp2.nowzMill(std.testing.io) - t0zz < 4000); }
test "NDJSON lines are frames, JSONL keeps them valid" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf4: [64]u8 = undefined; const got2 = try strm.ssezRead(allo, aren.allocator(), std.testing.io, url(&rig3, &buf4, "/ndjson"), .{ .priv = true, .time_mill = 5000 }); try std.testing.expectEqual(@as(usize, 2), got2.len); const out2 = try strm.jso2(aren.allocator(), got2); try std.testing.expectEqualStrings("{\"a\":1}\n{\"a\":2}\n", out2); const tex2 = try strm.jso2(aren.allocator(), &.{"plain text"}); try std.testing.expectEqualStrings("\"plain text\"\n", tex2); }
test "long-poll: repeated GETs until the frame cap" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf4: [64]u8 = undefined; const got2 = try strm.ssezRead(allo, aren.allocator(), std.testing.io, url(&rig3, &buf4, "/poll"), .{ .priv = true, .time_mill = 8000, .fra2 = 3, .repe = true }); try std.testing.expectEqual(@as(usize, 3), got2.len); try std.testing.expect(!std.mem.eql(u8, got2[0], got2[2])); }
test "bad status is a typed error; private host refused without the test flag" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf4: [64]u8 = undefined; try std.testing.expectError(error.BadStatus, strm.ssezRead(allo, aren.allocator(), std.testing.io, url(&rig3, &buf4, "/e403"), .{ .priv = true, .time_mill = 3000 })); const none = try strm.ssezRead(allo, aren.allocator(), std.testing.io, url(&rig3, &buf4, "/sse"), .{ .priv = false, .time_mill = 2000 }); try std.testing.expectEqual(@as(usize, 0), none.len); }
test "stream record is saved as kind strm, once" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf4: [64]u8 = undefined; const urlz = url(&rig3, &buf4, "/sse"); const got2 = try strm.ssezRead(allo, aren.allocator(), std.testing.io, urlz, .{ .priv = true, .time_mill = 5000 }); const body = try strm.jso2(aren.allocator(), got2); const out2 = try pipe.pageSave(aren.allocator(), std.testing.io, rig3.ladz.conf, &rig3.dbzz, rig3.dirz, urlz, null, .{ .code = 200, .ctyp = "application/x-ndjson", .body = body }); try std.testing.expectEqualStrings("new", out2.stat); try std.testing.expectEqualStrings("strm", out2.kind); const recz = (try rig3.reco("/sse")).?; try std.testing.expectEqualStrings("\"msg1\"\n\"msg2\"\n\"msg3\"\n\"msg4\"\n\"msg5\"\n", recz.body); }
test "WebSocket via Chrome: exact frame count, then a cap and a deadline" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); try rig3.skipNozz(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf4: [64]u8 = undefined; const got2 = try strm.wszzRead(&rig3.rndz, aren.allocator(), url(&rig3, &buf4, "/wspage"), .{ .time_mill = 8000 }); try std.testing.expectEqual(@as(usize, 5), got2.len); try std.testing.expectEqualStrings("tick 1", got2[0]); try std.testing.expectEqualStrings("tick 5", got2[4]); var buf2: [64]u8 = undefined; const cap2 = try strm.wszzRead(&rig3.rndz, aren.allocator(), url(&rig3, &buf2, "/wspage?inf"), .{ .time_mill = 8000, .fra2 = 3 }); try std.testing.expectEqual(@as(usize, 3), cap2.len); var buf3: [64]u8 = undefined; const t0zz = cdp2.nowzMill(std.testing.io); const dlzz = try strm.wszzRead(&rig3.rndz, aren.allocator(), url(&rig3, &buf3, "/wspage?inf"), .{ .time_mill = 1500 }); try std.testing.expect(dlzz.len >= 1 and dlzz.len < 100); try std.testing.expect(cdp2.nowzMill(std.testing.io) - t0zz < 4000); }
